"""Generated by Gate-Keeper {{version}}. Applies only to processing whose lawful basis is consent."""

from collections.abc import Callable
from dataclasses import dataclass
from datetime import datetime, timezone
from threading import Lock

from inveniotech.gatekeeper.consent import ConsentProvider, ConsentState, arguments


@dataclass(frozen=True)
class ConsentEvent:
    """Immutable event; withdrawal follows the same path as granting."""

    subject_id: str
    purpose: str
    kind: str
    time: datetime
    channel: str
    notice_version: str


class EventConsentProvider(ConsentProvider):
    """Example store; replace with durable storage before deployment."""

    def __init__(self, clock: Callable[[], datetime]) -> None:
        self._clock = clock
        self._events: list[ConsentEvent] = []
        self._lock = Lock()

    def record(self, subject_id: str, purpose: str, granted: bool, channel: str, notice_version: str) -> None:
        """Append after application authorisation; never update or remove an event."""
        arguments(subject_id, purpose)
        if not isinstance(granted, bool) or not channel.strip() or not notice_version.strip():
            raise ValueError("Supply the channel and notice version.")
        with self._lock:
            time = self._clock()
            if time.tzinfo is None or time.utcoffset() is None:
                raise ValueError("Supply a clock with a UTC offset.")
            self._events.append(ConsentEvent(subject_id, purpose, "granted" if granted else "withdrawn", time.astimezone(timezone.utc), channel, notice_version))

    def history(self) -> tuple[ConsentEvent, ...]:
        """Return an immutable copy for application-controlled history access."""
        with self._lock:
            return tuple(self._events)

    def get_state(self, subject_id: str, purpose: str) -> ConsentState:
        """Latest appended event wins for the pair; absence is denied."""
        with self._lock:
            for event in reversed(self._events):
                if event.subject_id == subject_id and event.purpose == purpose:
                    return "granted" if event.kind == "granted" else "denied"
        return "denied"
